CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, icon text NOT NULL, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, source_id text NOT NULL, title text NOT NULL, description text, thumbnail_ref text, duration_seconds integer, visible boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, availability text NOT NULL DEFAULT 'MISSING', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_type, source_id));
CREATE TABLE IF NOT EXISTS media_categories (media_item_id uuid NOT NULL REFERENCES media_items(id) ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY(media_item_id, category_id));
CREATE TABLE IF NOT EXISTS imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, source_id text NOT NULL, state text NOT NULL, title text, description text, duration_seconds integer, thumbnail_url text, media_item_id uuid REFERENCES media_items(id) ON DELETE SET NULL, error_code text, approved boolean NOT NULL DEFAULT false, requested_visible boolean NOT NULL DEFAULT false, requested_category_ids text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_type, source_id));
CREATE TABLE IF NOT EXISTS auth_config (id integer PRIMARY KEY, pin_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE media_items ALTER COLUMN duration_seconds TYPE double precision USING duration_seconds::double precision;
ALTER TABLE imports ALTER COLUMN duration_seconds TYPE double precision USING duration_seconds::double precision;
DO $$ BEGIN ALTER TABLE media_items ADD CONSTRAINT media_source_type_check CHECK (source_type IN ('YOUTUBE','LOCAL')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE media_items ADD CONSTRAINT media_availability_check CHECK (availability IN ('AVAILABLE','MISSING','UNAVAILABLE')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE imports ADD CONSTRAINT import_source_type_check CHECK (source_type IN ('YOUTUBE','LOCAL')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE imports ADD CONSTRAINT import_state_check CHECK (state IN ('EXTRACTING','PREVIEW','QUEUED','READY','FAILED')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
